import type { AssistantTurn } from '@/api/types'
import { citationLabel } from './format'

export const DRAFT_MARKING =
  'UNREVIEWED AI DRAFT — generated by Legal Lens from the attorney’s own documents. ' +
  'Not legal advice. The attorney remains responsible for all content and must verify every citation before use.'

export const OUTPUT_DISCLAIMER =
  'Attorney work-product aid generated by Legal Lens. Not legal advice. Verify every citation against the source document.'

const INCOMPLETE_MARKING =
  'INCOMPLETE OUTPUT — the response stream was interrupted and this text is partial.'

/**
 * Nuance #3 / FR-23, FR-24: the marking is part of the text, not paint on the
 * screen. Anything copied or exported carries its banner and its citations, so
 * a draft pasted into Word is still visibly a draft.
 */
export function turnToMarkdown(
  turn: AssistantTurn,
  opts: { includeCitations?: boolean } = {},
): string {
  const { includeCitations = true } = opts
  const out: string[] = []

  if (turn.kind === 'draft') out.push(`> **${DRAFT_MARKING}**`, '')
  if (turn.status === 'incomplete') out.push(`> **${INCOMPLETE_MARKING}**`, '')

  if (turn.kind === 'draft' && turn.draft) {
    out.push(`# ${turn.draft.title}`, '')
    const p = turn.draft.params
    if (p.questionPresented) out.push(`**Question presented.** ${p.questionPresented}`, '')
    for (const s of turn.draft.sections) {
      out.push(`## ${s.heading}`, '', s.bodyMd.trim(), '')
    }
  } else if (turn.kind === 'summary' && turn.summary) {
    const s = turn.summary
    out.push(`# Summary — ${s.documentName}`, '', `_${s.templateName}_`, '')
    for (const f of s.fields) {
      out.push(`## ${f.label}`, '')
      out.push(f.valueMd ? f.valueMd.trim() : '_Not addressed in this document._', '')
    }
    if (s.coverage) out.push(`_Coverage: ${s.coverage.note}_`, '')
  } else if (turn.refusal) {
    out.push('## Not answerable from your documents', '', turn.refusal.message, '')
    out.push(`_Queries run: ${turn.refusal.lookedFor.join('; ')}_`, '')
  } else {
    out.push(turn.text.trim(), '')
  }

  if (turn.scopeUsed) {
    const n = turn.scopeUsed.documentCount
    out.push(`_Scope searched: ${n} document${n === 1 ? '' : 's'}, ${turn.scopeUsed.pageCount} pages._`, '')
  }

  if (includeCitations && turn.citations.length > 0) {
    out.push('---', '', '### Citations', '')
    for (const c of turn.citations) {
      out.push(`${c.n}. ${citationLabel(c)} — \`${c.spanId}\``)
    }
    out.push('')
  }

  out.push('---', '', `_${turn.kind === 'draft' ? DRAFT_MARKING : OUTPUT_DISCLAIMER}_`)
  if (turn.traceId) out.push('', `<!-- trace: ${turn.traceId} -->`)

  return out.join('\n')
}

/** Plain text for pasting into an email — same markings, no markdown syntax. */
export function turnToPlainText(turn: AssistantTurn): string {
  return turnToMarkdown(turn)
    .replace(/^> \*\*(.+)\*\*$/gm, '$1')
    .replace(/^#{1,6} /gm, '')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/_(.+?)_/g, '$1')
    .replace(/`(.+?)`/g, '$1')
    .replace(/\[\[(\d+)\]\]/g, '[$1]')
    .replace(/<!--.*?-->/g, '')
    .trim()
}

export async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch {
    // Clipboard API is unavailable over plain http or without permission.
    try {
      const el = document.createElement('textarea')
      el.value = text
      el.setAttribute('readonly', '')
      el.style.position = 'fixed'
      el.style.opacity = '0'
      document.body.appendChild(el)
      el.select()
      const ok = document.execCommand('copy')
      document.body.removeChild(el)
      return ok
    } catch {
      return false
    }
  }
}

export function downloadMarkdown(filename: string, body: string): void {
  const blob = new Blob([body], { type: 'text/markdown;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename.endsWith('.md') ? filename : `${filename}.md`
  document.body.appendChild(a)
  a.click()
  a.remove()
  URL.revokeObjectURL(url)
}

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 60)
}
